from typing import Any, Dict
from fastapi._compat.v2 import _replace_refs

def test_replace_refs_no_ref():
    schema = {"type": "string"}
    old_name_to_new_name_map = {"OldName": "NewName"}
    # This should not raise KeyError
    result = _replace_refs(schema, old_name_to_new_name_map)
    assert result == {"type": "string"}

def test_replace_refs_with_ref():
    schema = {"$ref": "#/definitions/OldName"}
    old_name_to_new_name_map = {"OldName": "NewName"}
    # This should replace the ref
    result = _replace_refs(schema, old_name_to_new_name_map)
    assert "$ref" in result
    # We don't know the exact REF_TEMPLATE but it should be changed
    assert result["$ref"] != schema["$ref"]

if __name__ == "__main__":
    try:
        test_replace_refs_no_ref()
        print("test_replace_refs_no_ref passed")
        test_replace_refs_with_ref()
        print("test_replace_refs_with_ref passed")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

